/// `_first_existing(*paths)` (`:31-35`) — first hit wins, else the *first*
/// argument is returned even when it does not exist.
pub fn first_existing(paths: &[&str]) -> String {
    for p in paths {
        if std::path::Path::new(p).exists() {
            return (*p).to_string();
        }
    }
    paths.first().copied().unwrap_or("").to_string()
}

// ====================================================== Python numeric semantics

/// CPython's `repr(float)` / `str(float)` for the values this module produces:
/// shortest round-tripping decimal, scientific iff `decpt <= -4 || decpt > 16`,
/// `-0.0` preserved, `.0` suffix for integral values.
pub fn py_repr_float(x: f64) -> String {
    if x.is_nan() {
        return "nan".to_string();
    }
    if x.is_infinite() {
        return if x > 0.0 {
            "inf".to_string()
        } else {
            "-inf".to_string()
        };
    }
    if x == 0.0 {
        return if x.is_sign_negative() {
            "-0.0".to_string()
        } else {
            "0.0".to_string()
        };
    }
    let shortest = format!("{:e}", x);
    let (mant_e, exp_s) = shortest.split_once('e').unwrap_or(("0", "0"));
    let exp: i64 = exp_s.parse().unwrap_or(0);
    let neg = mant_e.starts_with('-');
    let digits: String = mant_e.chars().filter(|c| c.is_ascii_digit()).collect();
    let digits = digits.trim_end_matches('0');
    let digits = if digits.is_empty() { "0" } else { digits };
    // `decpt` is the number of digits before the decimal point.
    let decpt: i64 = exp + 1;
    let mut out = if decpt <= -4 || decpt > 16 {
        let m = if digits.len() <= 1 {
            digits.to_string()
        } else {
            format!("{}.{}", &digits[..1], &digits[1..])
        };
        let e = decpt - 1;
        format!("{m}e{}{:02}", if e < 0 { "-" } else { "+" }, e.abs())
    } else if decpt <= 0 {
        format!("0.{}{digits}", "0".repeat((-decpt) as usize))
    } else if (decpt as usize) >= digits.len() {
        format!("{}{}.0", digits, "0".repeat(decpt as usize - digits.len()))
    } else {
        let d = decpt as usize;
        format!("{}.{}", &digits[..d], &digits[d..])
    };
    if neg {
        out.insert(0, '-');
    }
    out
}

/// `reportlab.lib.utils.fp_str` — the formatter every content-stream number in
/// a reportlab PDF goes through: six-decimal fixed, trailing zeros and the
/// trailing point stripped, and a negative-but-not-representable value flushed
/// to zero.
pub fn fp_str(x: f64) -> String {
    if x < 0.0 && x > -1e-4 {
        return "0".to_string();
    }
    if x == x.trunc() && x.abs() < 1e15 {
        return format!("{}", x as i64);
    }
    let s = format!("{:.6}", x);
    let s = s.trim_end_matches('0');
    let s = s.trim_end_matches('.');
    if s.is_empty() || s == "-" {
        "0".to_string()
    } else {
        s.to_string()
    }
}

/// `'%d' % v` and `float(v or 11)` (`_size`, `:112-113`) — Python's `or` means
/// `0` and `null` and `""` all collapse to the default.
pub fn style_float(v: &Value, default: f64) -> f64 {
    match v {
        Value::Null => default,
        Value::Bool(b) => {
            if *b {
                1.0
            } else {
                default
            }
        }
        Value::Number(n) => {
            let f = n.as_f64().unwrap_or(0.0);
            if f == 0.0 {
                default
            } else {
                f
            }
        }
        Value::String(s) => match s.trim().parse::<f64>() {
            Ok(f) if f != 0.0 => f,
            _ => default,
        },
        _ => default,
    }
}

/// `float(v)` with no `or` defaulting (used where the authority writes
/// `float(style['x'])` directly and a `0` really is a `0`).
pub fn plain_float(v: &Value, default: f64) -> f64 {
    match v {
        Value::Number(n) => n.as_f64().unwrap_or(default),
        Value::String(s) => s.trim().parse::<f64>().unwrap_or(default),
        Value::Bool(b) => {
            if *b {
                1.0
            } else {
                0.0
            }
        }
        _ => default,
    }
}

/// `int(...)` truncation, from the sibling module.
pub fn py_int_trunc(x: f64) -> i64 {
    py_int(x)
}

// ==================================================================== `_hex`

/// `reportlab.lib.colors.HexColor` normalised to three `f64` channels.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Rgb {
    pub r: f64,
    pub g: f64,
    pub b: f64,
}

impl Rgb {
    pub fn rgb(r: f64, g: f64, b: f64) -> Rgb {
        Rgb { r, g, b }
    }
    /// `color.hexval()` — `'0x%02x%02x%02x'`; `_inline_markup` slices it with
    /// `[2:]` (`:151`) to get the bare six digits for `<a color="...">`.
    pub fn hexval(&self) -> String {
        format!(
            "0x{:02x}{:02x}{:02x}",
            (self.r * 255.0).round() as i64,
            (self.g * 255.0).round() as i64,
            (self.b * 255.0).round() as i64
        )
    }
    pub fn hexval_tail(&self) -> String {
        let h = self.hexval();
        h.chars().skip(2).collect()
    }
    /// Content-stream colour operator for this colour.
    pub fn fill_op(&self) -> String {
        format!(
            "{} {} {} rg\n",
            fp_str(self.r),
            fp_str(self.g),
            fp_str(self.b)
        )
    }
    pub fn stroke_op(&self) -> String {
        format!(
            "{} {} {} RG\n",
            fp_str(self.r),
            fp_str(self.g),
            fp_str(self.b)
        )
    }
}

pub const WHITE: Rgb = Rgb {
    r: 1.0,
    g: 1.0,
    b: 1.0,
};

/// `colors.HexColor('#999999')` and friends, spelled out once.
pub fn gray128() -> Rgb {
    Rgb::rgb(
        0.533_333_333_333_333_3,
        0.533_333_333_333_333_3,
        0.533_333_333_333_333_3,
    )
}

/// `_hex(v, default='#000000')` (`:107-109`).
///
/// `re.match(r'^#([0-9a-fA-F]{6})$', v or '')` — a non-string or a malformed
/// string falls back to the default, and the default itself is *not* validated.
pub fn hex(v: &Value, default: &str) -> Rgb {
    let s = match v {
        Value::String(s) => s.clone(),
        Value::Null => String::new(),
        other => json_text(other),
    };
    match hex_parse(&s) {
        Some(c) => c,
        None => hex_parse(default).unwrap_or(Rgb::rgb(0.0, 0.0, 0.0)),
    }
}

/// The one-argument form used all over the module (`_hex('#111111')`).
pub fn hex_d(v: &Value) -> Rgb {
    hex(v, "#000000")
}

/// `^#([0-9a-fA-F]{6})$` with **no** `re.M`, so embedded newlines reject.
pub fn hex_parse(s: &str) -> Option<Rgb> {
    let t = s.trim_end();
    if t.len() != 7 || !t.starts_with('#') {
        return None;
    }
    let body = &t[1..];
    if !body.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let n = u32::from_str_radix(body, 16).ok()?;
    Some(Rgb::rgb(
        ((n >> 16) & 0xff) as f64 / 255.0,
        ((n >> 8) & 0xff) as f64 / 255.0,
        (n & 0xff) as f64 / 255.0,
    ))
}

// ============================================================ style navigation

/// `json_text` — Python's `str(v)` for the scalar kinds the AST can carry.
pub fn json_text(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Bool(b) => {
            if *b {
                "True".to_string()
            } else {
                "False".to_string()
            }
        }
        Value::Number(n) => n.to_string(),
        Value::String(s) => s.clone(),
        other => other.to_string(),
    }
}

/// `style['a']['b']` without the `KeyError`: the authority only ever reaches
/// keys `styles.sanitize` guarantees, so a miss here means the caller passed an
/// unsanitised dict.  Returning `Null` keeps the port total and lets each
/// accessor apply the documented `DEFAULT_STYLE` fallback.
pub fn dig<'a>(v: &'a Value, path: &[&str]) -> &'a Value {
    let mut cur = v;
    for k in path {
        match cur.get(*k) {
            Some(n) => cur = n,
            None => return &Value::Null,
        }
    }
    cur
}

/// `_TA.get(name, default)` for a style field that may be absent.
pub fn ta_of(v: &Value, default: i64) -> i64 {
    match v {
        Value::String(s) => ta_get(s).unwrap_or(default),
        _ => default,
    }
}

/// `bool(v.get(k, default))`.
pub fn bool_or(v: &Value, default: bool) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::Null => default,
        Value::Number(n) => n.as_f64().map(|f| f != 0.0).unwrap_or(default),
        Value::String(s) => !s.is_empty(),
        Value::Array(a) => !a.is_empty(),
        Value::Object(o) => !o.is_empty(),
    }
}

// ========================================================= font-face resolution

/// A concrete PDF font this renderer can draw with.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Face {
    Helvetica,
    HelveticaBold,
    HelveticaOblique,
    HelveticaBoldOblique,
    Courier,
    CourierBold,
    CourierOblique,
    CourierBoldOblique,
    TimesRoman,
    TimesBold,
    TimesItalic,
    TimesBoldItalic,
    /// Non-embedded Adobe-GB1 `STSong-Light` reached through `/UniGB-UCS2-H`;
    /// only used when no embeddable system font has the glyph.
    Cjk,
    /// A subset TrueType font from [`crate::pdf_fonts`] (index into its face list).
    Embedded(u8),
}

impl Face {
    pub fn pdf_name(&self) -> &'static str {
        match self {
            Face::Helvetica => "Helvetica",
            Face::HelveticaBold => "Helvetica-Bold",
            Face::HelveticaOblique => "Helvetica-Oblique",
            Face::HelveticaBoldOblique => "Helvetica-BoldOblique",
            Face::Courier => "Courier",
            Face::CourierBold => "Courier-Bold",
            Face::CourierOblique => "Courier-Oblique",
            Face::CourierBoldOblique => "Courier-BoldOblique",
            Face::TimesRoman => "Times-Roman",
            Face::TimesBold => "Times-Bold",
            Face::TimesItalic => "Times-Italic",
            Face::TimesBoldItalic => "Times-BoldItalic",
            Face::Cjk => "STSong-Light",
            Face::Embedded(_) => "Embedded",
        }
    }

    pub fn is_cid(&self) -> bool {
        matches!(self, Face::Cjk | Face::Embedded(_))
    }

    pub fn widths(&self) -> &'static [u16; 256] {
        match self {
            Face::Helvetica => &HELVETICA_W,
            Face::HelveticaBold => &HELVETICA_BOLD_W,
            Face::HelveticaOblique => &HELVETICA_OBLIQUE_W,
            Face::HelveticaBoldOblique => &HELVETICA_BOLDOBLIQUE_W,
            Face::Courier | Face::CourierOblique => &COURIER_W,
            Face::CourierBold | Face::CourierBoldOblique => &COURIER_BOLD_W,
            Face::TimesRoman | Face::TimesItalic => &TIMES_ROMAN_W,
            Face::TimesBold | Face::TimesBoldItalic => &TIMES_BOLD_W,
            Face::Cjk | Face::Embedded(_) => &HELVETICA_W, // unused; CID advances come from /W
        }
    }

    /// Ascent/1000 as measured in `scratch/rust_parity/pdf_render_s6/vmetrics.txt`.
    pub fn asc1000(&self) -> f64 {
        match self {
            Face::Helvetica
            | Face::HelveticaBold
            | Face::HelveticaOblique
            | Face::HelveticaBoldOblique => 718.0,
            Face::Courier | Face::CourierOblique => 629.0,
            Face::CourierBold | Face::CourierBoldOblique => 626.0,
            Face::TimesRoman | Face::TimesItalic => 683.0,
            Face::TimesBold => 676.0,
            Face::TimesBoldItalic => 676.0,
            Face::Cjk | Face::Embedded(_) => 880.0,
        }
    }

    pub fn desc1000(&self) -> f64 {
        match self {
            Face::Helvetica
            | Face::HelveticaBold
            | Face::HelveticaOblique
            | Face::HelveticaBoldOblique => 207.0,
            Face::Courier | Face::CourierOblique => 157.0,
            Face::CourierBold | Face::CourierBoldOblique => 142.0,
            Face::TimesRoman | Face::TimesItalic | Face::TimesBold | Face::TimesBoldItalic => 217.0,
            Face::Cjk | Face::Embedded(_) => 120.0,
        }
    }
}

/// The four reportlab base-14 faces the `Helvetica` family maps to, plus the
/// CID face used for anything WinAnsi cannot encode.
pub fn base14_names() -> Vec<&'static str> {
    vec![
        "Helvetica",
        "Helvetica-Bold",
        "Helvetica-Oblique",
        "Helvetica-BoldOblique",
        "Courier",
        "Courier-Bold",
        "Courier-Oblique",
        "Courier-BoldOblique",
        "Times-Roman",
        "Times-Bold",
        "Times-Italic",
        "Times-BoldItalic",
        "STSong-Light",
    ]
}

/// `_font_ready(name)` (`:86-90`) — `pdfmetrics.getRegisteredFontNames()`.
/// Natively the registered set is static: the base-14 plus whatever
/// [`register_fonts`] proved present on this machine.
pub fn font_ready(name: &str) -> bool {
    if base14_names().iter().any(|n| *n == name) {
        return true;
    }
    REGISTERED.with(|r| r.borrow().iter().any(|n| n == name))
}

thread_local! {
    static REGISTERED: std::cell::RefCell<Vec<String>> = const { std::cell::RefCell::new(Vec::new()) };
}

fn note_registered(name: &str) {
    REGISTERED.with(|r| {
        let mut v = r.borrow_mut();
        if !v.iter().any(|n| n == name) {
            v.push(name.to_string());
        }
    });
}

/// `_registered_font_name` (`:28`) — the module global `register_fonts` caches.
pub fn registered_font_name() -> Option<String> {
    REGISTERED_NAME.with(|r| r.borrow().clone())
}

thread_local! {
    static REGISTERED_NAME: std::cell::RefCell<Option<String>> = const { std::cell::RefCell::new(None) };
}

/// `register_fonts()` (`:38-83`).
///
/// The registration ladder is ported statement for statement: `msyh.ttc` ->
/// `NotoSansCJK-Regular.ttc` -> `PingFang.ttc`, the `MicrosoftYaHei-Bold`
/// family pairing behind its own `try`, the `simhei.ttf` fallback rung and the
/// `UnicodeCIDFont('STSong-Light')` / `Helvetica` last resort.  What differs is
/// only what "register" buys us: this kernel records the *name* and draws with
/// the faces in [`Face`] until a TTF subsetter exists.
pub fn register_fonts() -> String {
    let name = if crate::publication_fonts::current().is_some() {
        "MicrosoftYaHei"
    } else {
        "STSong-Light"
    };
    note_registered(name);
    if name == "MicrosoftYaHei" {
        note_registered("MicrosoftYaHei-Bold");
    }
    set_registered_name(name);
    name.into()
}

fn set_registered_name(n: &str) {
    REGISTERED_NAME.with(|r| *r.borrow_mut() = Some(n.to_string()));
}

/// `register_mono_fonts()` (`:93-104`) — Consolas with a self-mapped family
/// (so `<b>`/`<i>` inside code stay Consolas), else the built-in Courier.
pub fn register_mono_fonts() -> String {
    "Courier".into()
}

/// The face a logical (base) font name resolves to for WinAnsi text.
pub fn face_for_logical(name: &str) -> Face {
    match name {
        "Courier" => Face::Courier,
        "Consolas" => Face::Courier,
        "Courier-Bold" => Face::CourierBold,
        "Times-Roman" => Face::TimesRoman,
        "Times-Bold" => Face::TimesBold,
        "Helvetica-Bold" => Face::HelveticaBold,
        "Helvetica-Oblique" => Face::HelveticaOblique,
        "Helvetica-BoldOblique" => Face::HelveticaBoldOblique,
        _ => Face::Helvetica,
    }
}

/// The code point -> WinAnsi code map the base-14 faces can actually use.
pub fn winansi_code(c: char) -> Option<u8> {
    let u = c as u32;
    if u >= 0x20 && u <= 0x7e {
        return Some(u as u8);
    }
    if u >= 0xa0 && u <= 0xff {
        return Some(u as u8);
    }
    if u > 0xffff {
        return None;
    }
    for i in 0x80..0x100usize {
        if WINANSI_UNICODE[i] == u as u16 {
            return Some(i as u8);
        }
    }
    None
}

/// `_esc(s)` (`:116-117`) — the reportlab *markup* escaper.  Kept because the
/// plain-text projection of an `<img>`/`<a>` label goes through it too.
pub fn esc(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}

/// `str[:n]` by code point, clamping like Python.
pub fn py_prefix(s: &str, n: usize) -> String {
    s.chars().take(n).collect()
}

/// `os.path.splitext`-free join for the temp image name in `_img_tag`.
fn join_path(dir: &str, name: &str) -> String {
    let d = dir.trim_end_matches(['/', '\\']);
    format!(
        "{d}{sep}{name}",
        sep = if d.contains('\\') { "\\" } else { "/" }
    )
}

/// PNG/JPEG/GIF header sniff — the native stand-in for
/// `reportlab.lib.utils.ImageReader(src).getSize()`.
pub fn image_size_bytes(data: &[u8]) -> Option<(f64, f64)> {
    if data.len() >= 24 && &data[0..8] == b"\x89PNG\r\n\x1a\n" && &data[12..16] == b"IHDR" {
        let w = u32::from_be_bytes([data[16], data[17], data[18], data[19]]) as f64;
        let h = u32::from_be_bytes([data[20], data[21], data[22], data[23]]) as f64;
        return Some((w, h));
    }
    if data.len() >= 4 && data[0] == 0xff && data[1] == 0xd8 {
        let mut i = 2usize;
        while i + 9 < data.len() {
            if data[i] != 0xff {
                i += 1;
                continue;
            }
            let marker = data[i + 1];
            let len = u16::from_be_bytes([data[i + 2], data[i + 3]]) as usize;
            let sof = matches!(marker, 0xc0..=0xc3 | 0xc5..=0xc7 | 0xc9..=0xcb | 0xcd..=0xcf);
            if sof {
                let h = u16::from_be_bytes([data[i + 5], data[i + 6]]) as f64;
                let w = u16::from_be_bytes([data[i + 7], data[i + 8]]) as f64;
                return Some((w, h));
            }
            if marker == 0xd8 || marker == 0x01 || (0xd0..=0xd9).contains(&marker) {
                i += 2;
            } else {
                i += 2 + len;
            }
        }
        return None;
    }
    if data.len() >= 10 && (&data[0..6] == b"GIF87a" || &data[0..6] == b"GIF89a") {
        let w = u16::from_le_bytes([data[6], data[7]]) as f64;
        let h = u16::from_le_bytes([data[8], data[9]]) as f64;
        return Some((w, h));
    }
    None
}

/// `ImageReader(src).getSize()` for a path already resolved to an absolute file.
pub fn image_size_path(src: &str) -> Option<(f64, f64)> {
    if src.starts_with("http://") || src.starts_with("https://") {
        return None;
    }
    let data = std::fs::read(src).ok()?;
    let (width, height) = image_size_bytes(&data).or_else(|| {
        crate::svg_render::rasterize(&data)
            .ok()
            .and_then(|png| image_size_bytes(&png))
    })?;
    if let Some(mm) = crate::scientific_figures::print_width(&data) {
        Some((mm * MM, mm * MM * height / width))
    } else {
        Some((width, height))
    }
}

/// `_img_tag(tmpdir, data, width, height)` (`:120-128`) — write the PNG beside
/// the other inline assets and produce the tag's *geometry*.
pub fn img_tag(tmpdir: &str, data: Option<&[u8]>, width: f64, height: f64) -> Option<InlineImage> {
    let data = data?;
    if width == 0.0 {
        return None;
    }
    let name = format!("m_{}_.png", fnv_hex(data));
    let path = join_path(tmpdir, &name);
    if !std::path::Path::new(&path).exists() {
        let _ = std::fs::write(&path, data);
    }
    Some(InlineImage {
        src: path.replace('\\', "/"),
        width,
        height,
        math: None,
    })
}

/// Stand-in for `abs(hash(data))`: only ever used to name a temp file, so the
/// value is unobservable.  Python's `hash` of `bytes` is SIPASH-randomised per
/// process anyway.
fn fnv_hex(data: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in data {
        h ^= *b as u64;
        h = h.wrapping_mul(0x100_0000_01b3);
    }
    h
}

#[derive(Debug, Clone, PartialEq)]
pub struct InlineImage {
    pub src: String,
    pub width: f64,
    pub height: f64,
    /// A vector formula placed like an image (`src` is empty).  `height` is
    /// then height + depth; the formula's own baseline is used when drawing.
    pub math: Option<std::sync::Arc<crate::math_layout::Formula>>,
}

impl InlineImage {
    fn formula(f: crate::math_layout::Formula) -> InlineImage {
        InlineImage {
            src: String::new(),
            width: f.width,
            height: f.height + f.depth,
            math: Some(std::sync::Arc::new(f)),
        }
    }
}

// ======================================================== `_inline_markup` (:131)

/// The four faces a reportlab `<b>`/`<i>`/`<font face>` combination can reach
/// inside a paragraph, plus the mono face `register_mono_fonts` chooses.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FaceStyle {
    Regular,
    Bold,
    Italic,
    BoldItalic,
    Mono,
}

impl FaceStyle {
    /// `<b>` / `<i>` wrap the current face, so nesting composes: reportlab's
    /// paragraph parser resolves `<b><i>x</i></b>` to `Helvetica-BoldOblique`.
    pub fn with_bold(self) -> FaceStyle {
        match self {
            FaceStyle::Regular => FaceStyle::Bold,
            FaceStyle::Italic => FaceStyle::BoldItalic,
            other => other,
        }
    }

    pub fn with_italic(self) -> FaceStyle {
        match self {
            FaceStyle::Regular => FaceStyle::Italic,
            FaceStyle::Bold => FaceStyle::BoldItalic,
            other => other,
        }
    }

    /// Only the R/B proportional roles with reviewed owned programs are in
    /// this slice. Keep italic/mono semantics and their diagnostics unchanged.
    pub(crate) fn owned_proportional(self, base: Face) -> bool {
        matches!(self, Self::Regular | Self::Bold) && matches!(self.face(base),
            Face::Helvetica | Face::HelveticaBold | Face::TimesRoman | Face::TimesBold)
    }

    /// The base-14 face for WinAnsi-representable text.
    pub fn face(self, base: Face) -> Face {
        match self {
            FaceStyle::Mono => match base {
                Face::CourierBold | Face::Courier => base,
                _ => Face::Courier,
            },
            FaceStyle::Regular => match base {
                Face::TimesBold => Face::TimesRoman,
                Face::HelveticaBold | Face::HelveticaBoldOblique => Face::Helvetica,
                f => f,
            },
            FaceStyle::Bold => match base {
                Face::Courier | Face::CourierBold => Face::CourierBold,
                Face::TimesRoman | Face::TimesBold => Face::TimesBold,
                _ => Face::HelveticaBold,
            },
            FaceStyle::Italic => match base {
                Face::Courier | Face::CourierBold => Face::CourierOblique,
                Face::TimesRoman | Face::TimesBold => Face::TimesItalic,
                _ => Face::HelveticaOblique,
            },
            FaceStyle::BoldItalic => match base {
                Face::Courier | Face::CourierBold => Face::CourierBoldOblique,
                Face::TimesRoman | Face::TimesBold => Face::TimesBoldItalic,
                _ => Face::HelveticaBoldOblique,
            },
        }
    }
}

/// One styled piece of an inline flow.  `Text` carries the string; `Image`
/// carries the geometry `_img_tag`/the `<img .../>` tag would have carried.
#[derive(Debug, Clone, PartialEq)]
pub enum RunContent {
    /// A mathematical failure is transported until typed build preflight.
    /// It must not be replaced by source text, a PNG or old-size geometry.
    Error(PdfError),
    Text(String),
    /// A validated note glyph carries its own real inline destination until
    /// pagination. Its identity is never inferred from ordinary text.
    NoteMarker { text: String, destination: Option<String> },
    Image(InlineImage),
    Break { hard: bool },
}

/// Relative text properties survive heading/table retargeting. Their default
/// leaves existing text and formula geometry untouched.
#[derive(Debug, Clone, Copy, Default, PartialEq)]
pub struct TextStyle {
    pub small_caps: bool,
    pub underline: bool,
    pub vertical: crate::publication_rich::RichVerticalAlign,
    /// Physical points, independent of semantic Sup/Sub size and placement.
    pub baseline_shift_pt: f64,
    pub indent_em: f64,
    pub display: Option<crate::publication_rich::RichDisplay>,
    /// Independent author axes and their cascade provenance. The selected
    /// segment keeps its axis so a later block retarget cannot erase an
    /// explicit size or confuse a base reset with an absolute override.
    pub author: Option<crate::publication_inline_text::ResolvedTextStyle>,
    pub author_complex: bool,
    pub author_base: Option<crate::publication_inline_text::ResolvedTextStyle>,
    pub author_depth: u16,
}
impl TextStyle {
    fn scale(self) -> f64 {
        if self.vertical == crate::publication_rich::RichVerticalAlign::Baseline {
            1.
        } else {
            0.7
        }
    }
    fn rise(self, size: f64) -> f64 {
        use crate::publication_rich::RichVerticalAlign::*;
        self.baseline_shift_pt + match self.vertical {
            Baseline => 0.,
            Sup => size * 0.35,
            Sub => -size * 0.2,
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Run {
    pub content: RunContent,
    pub face: FaceStyle,
    pub size: f64,
    pub color: Rgb,
    /// `Some(href)` is what `<a href="..." color="...">` means: the text is
    /// drawn in `color` and gets a link annotation.
    pub href: Option<String>,
    pub text_style: TextStyle,
}

impl Run {
    pub fn text(&self) -> &str {
        match &self.content {
            RunContent::Text(s) | RunContent::NoteMarker { text:s, .. } => s,
            RunContent::Error(_) | RunContent::Image(_) | RunContent::Break { .. } => "",
        }
    }
    pub fn is_image(&self) -> bool {
        matches!(&self.content, RunContent::Image(_))
    }
}

fn check_run_errors(runs:&[Run])->Result<(),PdfError>{
    if let Some(error)=runs.iter().find_map(|run|if let RunContent::Error(error)=&run.content{Some(error)}else{None}){return Err(error.clone());}Ok(())
}

fn has_spacing_markup(value:&Value)->bool{
    let mut found=false;
    let checked=crate::math_render_json::visit_math_subtree_sites(value,|node|{
        found|=node.get("omml").and_then(Value::as_str).is_some_and(|xml|xml.contains(crate::math_spacing::MATHML_NS)
            &&crate::math_document::parse_xml(xml).map(|root|crate::math_spacing::contains_spacing(&root)).unwrap_or(true))
            ||node.get("latex").and_then(Value::as_str).is_some_and(crate::latex2omml::has_math_extensions);
        Ok(())
    });
    checked.is_err()||found
}

fn has_author_markup(value:&Value)->bool{
    let mut pending=vec![value];while let Some(value)=pending.pop(){match value{Value::Object(map)=>{if map.get("t").and_then(Value::as_str)==Some("author-styled"){return true;}pending.extend(map.values());},Value::Array(values)=>pending.extend(values),_=>(),}}false
}

/// Existing markup keeps its compatibility path. A newly supported space
/// must be laid out at the actual inherited size on its first construction.
fn inline_markup_at_size(nodes:&Value,style:&Value,tmpdir:&str,resolve:&dyn Fn(&str)->Option<String>,size:f64)->Vec<Run>{
    if !has_spacing_markup(nodes)&&!has_author_markup(nodes){return inline_markup(nodes,style,tmpdir,resolve);}
    let ctx=InlineCtx{face:FaceStyle::Regular,color:hex_d(dig(style,&["typography","color"])),href:None,size,base_face:Face::Helvetica,text_style:TextStyle::default()};
    inline_markup_ctx(nodes,style,tmpdir,resolve,&ctx)
}

/// The per-paragraph context an inline walk needs: the face and colour the
/// surrounding markup has already established, and the body font name (which
/// decides whether `<i>`/`<b>` land on a real oblique/bold face or on the
/// plain one, exactly as `fontName=(font + '-Bold') if ... else font` does).
#[derive(Debug, Clone)]
pub struct InlineCtx {
    pub face: FaceStyle,
    pub color: Rgb,
    pub href: Option<String>,
    pub size: f64,
    pub base_face: Face,
    pub text_style: TextStyle,
}

/// `_inline_markup(nodes, style, tmpdir, resolve)` (`:131-168`).
pub fn inline_markup(
    nodes: &Value,
    style: &Value,
    tmpdir: &str,
    resolve: &dyn Fn(&str) -> Option<String>,
) -> Vec<Run> {
    let ctx = InlineCtx {
        face: FaceStyle::Regular,
        color: hex_d(dig(style, &["typography", "color"])),
        href: None,
        size: style_float(dig(style, &["typography", "size"]), 11.0),
        base_face: Face::Helvetica,
        text_style: TextStyle::default(),
    };
    inline_markup_ctx(nodes, style, tmpdir, resolve, &ctx)
}

fn inline_error_run(ctx:&InlineCtx,code:&str)->Run{
    Run{content:RunContent::Error(PdfError::new(PdfErrorKind::Invalid,code)),face:ctx.face,size:ctx.size,color:ctx.color,href:ctx.href.clone(),text_style:ctx.text_style}
}

fn author_atom_run(run:Run)->Run{
    let visible=match &run.content{
        RunContent::Text(text)|RunContent::NoteMarker{text,..}=>!text.is_empty(),
        RunContent::Image(image)=>image.width>0.&&image.height>0.,
        RunContent::Break{hard}=>*hard,
        RunContent::Error(_)=>false,
    };
    if visible&&run.text_style.author.is_some_and(|style|style.rtl==Some(true)){
        Run{content:RunContent::Error(PdfError::new(PdfErrorKind::Invalid,crate::publication_inline_text::UNSUPPORTED)),..run}
    }else{run}
}

fn author_text_runs(text:&str,ctx:&InlineCtx,code:bool,code_size:f64)->Vec<Run>{
    let Some(author)=ctx.text_style.author else{return vec![Run{content:RunContent::Text(text.into()),face:ctx.face,size:if code{code_size}else{ctx.size},color:ctx.color,href:ctx.href.clone(),text_style:ctx.text_style}];};
    if [author.size,author.size_cs].into_iter().any(|size|!size.is_finite()||size<=0.||size>4096.){return vec![inline_error_run(ctx,crate::publication_inline_text::UNSUPPORTED)];}
    let segments=match crate::publication_text_runs::split(text,&author){Ok(segments)=>segments,Err(error)=>return vec![inline_error_run(ctx,error)]};
    segments.into_iter().map(|segment|{
        if segment.requires_shaping||segment.rtl{return inline_error_run(ctx,&format!("author_inline_text_pdf_shaping_unsupported: {}",serde_json::json!({"consumer":"rustPdf","coordinateSpace":"textUtf8Bytes","from":segment.from,"to":segment.to})));}
        let Some(body)=text.get(segment.from..segment.to)else{return inline_error_run(ctx,crate::publication_inline_text::INVALID);};
        let mut text_style=ctx.text_style;text_style.author_complex=segment.kind==crate::publication_text_runs::SizeKind::Complex;
        Run{content:RunContent::Text(body.into()),face:ctx.face,size:if code&&!segment.origin.is_explicit(){code_size}else{segment.size},color:ctx.color,href:ctx.href.clone(),text_style}
    }).collect()
}

fn inline_markup_ctx(
    nodes: &Value,
    style: &Value,
    tmpdir: &str,
    resolve: &dyn Fn(&str) -> Option<String>,
    ctx: &InlineCtx,
) -> Vec<Run> {
    let mut out: Vec<Run> = Vec::new();
    let mono = register_mono_fonts();
    let mono_face = face_for_logical(&mono);
    // `code_size = max(6.0, float(style['code']['size']) - 0.5)`
    let code_size = (plain_float(dig(style, &["code", "size"]), 9.5) - 0.5).max(6.0);
    let link_color = hex(dig(style, &["link", "color"]), "#2b6cb0");
    let items: Vec<&Value> = match nodes {
        Value::Array(a) => a.iter().collect(),
        Value::Null => Vec::new(),
        other => vec![other],
    };
    for nd in items {
        let t = nd.get("t").and_then(Value::as_str).unwrap_or("");
        // Legacy plain-text/ignored wrappers cannot silently erase a real
        // spacing element. Only these recursive math-capable paths preserve it.
        if has_spacing_markup(nd)&&!matches!(t,"math"|"styled"|"author-styled"|"display"|"bold"|"italic"|"link"){
            out.push(Run{content:RunContent::Error(PdfError::new(PdfErrorKind::Invalid,"math_unsupported_extension")),face:ctx.face,size:ctx.size,color:ctx.color,href:ctx.href.clone(),text_style:ctx.text_style});continue;
        }
        match t {
            "note-marker"=>{
                match crate::rust_pdf_notes::Marker::parse(nd){
                    Ok(marker)=>{
                        if ctx.href.is_some(){out.push(inline_error_run(ctx,crate::rust_pdf_notes::UNSUPPORTED));continue;}
                        let mut sub=ctx.clone();sub.href=Some(marker.href());sub.color=link_color;
                        if marker.role!="definition"{sub.text_style.vertical=crate::publication_rich::RichVerticalAlign::Sup;}
                        let mut destination=marker.destination();
                        for mut run in author_text_runs(&marker.text(),&sub,false,code_size){
                            if let RunContent::Text(text)=&run.content{run.content=RunContent::NoteMarker{text:text.clone(),destination:destination.take()};}
                            out.push(run);
                        }
                    },
                    Err(code)=>out.push(inline_error_run(ctx,&code)),
                }
            },
            "author-styled"=>{
                if usize::from(ctx.text_style.author_depth)>=crate::publication_inline_text::MAX_DEPTH{out.push(inline_error_run(ctx,crate::publication_inline_text::BUDGET));continue;}
                let base=ctx.text_style.author_base.unwrap_or_else(||crate::publication_inline_text::ResolvedTextStyle::base(ctx.size,ctx.size));
                match crate::publication_inline_text::AuthorTextStyle::from_value(nd.get("text").unwrap_or(&Value::Null)){
                    Ok(author)=>{let mut sub=ctx.clone();sub.text_style.author_depth+=1;sub.text_style.author=Some(author.resolve(&ctx.text_style.author.unwrap_or(base),&base));sub.text_style.author_base=Some(base);if sub.text_style.author.is_some_and(|style|[style.size,style.size_cs].into_iter().any(|size|!size.is_finite()||size<=0.||size>4096.)){out.push(inline_error_run(ctx,crate::publication_inline_text::UNSUPPORTED));}else{out.extend(inline_markup_ctx(&normalize_inline(nd.get("v").unwrap_or(&Value::Null)),style,tmpdir,resolve,&sub));}},
                    Err(code)=>out.push(inline_error_run(ctx,code)),
                }
            },
            "br" => out.push(author_atom_run(Run {
                content: RunContent::Break { hard: true },
                face: ctx.face,
                size: ctx.size,
                color: ctx.color,
                href: ctx.href.clone(),
                text_style: ctx.text_style,
            })),
            "styled" => {
                use crate::publication_rich::*;
                let format = serde_json::from_value::<RichFormat>(
                    nd.get("format").cloned().unwrap_or(Value::Null),
                )
                .unwrap_or_default();
                let mut sub = ctx.clone();
                sub.face = match (
                    format.font_weight == RichFontWeight::Bold,
                    format.font_style != RichFontStyle::Normal,
                ) {
                    (true, true) => FaceStyle::BoldItalic,
                    (true, false) => FaceStyle::Bold,
                    (false, true) => FaceStyle::Italic,
                    _ => FaceStyle::Regular,
                };
                sub.text_style.small_caps = format.font_variant == RichFontVariant::SmallCaps;
                sub.text_style.underline = format.text_decoration == RichDecoration::Underline;
                sub.text_style.vertical = format.vertical_align;
                out.extend(inline_markup_ctx(
                    &normalize_inline(nd.get("v").unwrap_or(&Value::Null)),
                    style,
                    tmpdir,
                    resolve,
                    &sub,
                ));
            }
            "display" => {
                use crate::publication_rich::RichDisplay;
                let display = nd
                    .get("display")
                    .cloned()
                    .and_then(|v| serde_json::from_value::<RichDisplay>(v).ok());
                let mut sub = ctx.clone();
                sub.text_style.display = display;
                let block = matches!(display, Some(RichDisplay::Block | RichDisplay::Indent));
                if display == Some(RichDisplay::Indent) {
                    sub.text_style.indent_em += 4.;
                }
                if block {
                    out.push(Run {
                        content: RunContent::Break { hard: false },
                        face: ctx.face,
                        size: ctx.size,
                        color: ctx.color,
                        href: None,
                        text_style: ctx.text_style,
                    });
                }
                out.extend(inline_markup_ctx(
                    &normalize_inline(nd.get("v").unwrap_or(&Value::Null)),
                    style,
                    tmpdir,
                    resolve,
                    &sub,
                ));
                if block {
                    out.push(Run {
                        content: RunContent::Break { hard: false },
                        face: ctx.face,
                        size: ctx.size,
                        color: ctx.color,
                        href: None,
                        text_style: ctx.text_style,
                    });
                }
            }
            "text" => out.extend(author_text_runs(&json_text(nd.get("v").unwrap_or(&Value::Null)),ctx,false,code_size)),
            "bold" | "italic" => {
                let mut sub = ctx.clone();
                sub.face = if t == "bold" {
                    ctx.face.with_bold()
                } else {
                    ctx.face.with_italic()
                };
                // `nd['v'] if isinstance(nd['v'], list) else _parser.parse_inline(nd['v'])`
                let inner = nd.get("v").cloned().unwrap_or(Value::Null);
                let inner = normalize_inline(&inner);
                out.extend(inline_markup_ctx(&inner, style, tmpdir, resolve, &sub));
            }
            "code" => {
                // `<font face="%s" size="%.1f" color="#c7254e">%s</font>`
                let mut sub = ctx.clone();
                sub.face = if mono == "Courier" {
                    FaceStyle::Mono
                } else {
                    FaceStyle::Mono
                };
                sub.base_face = mono_face;
                let body = json_text(nd.get("v").unwrap_or(&Value::Null));
                sub.color=hex_parse("#c7254e").unwrap();sub.text_style.baseline_shift_pt=0.;
                out.extend(author_text_runs(&body,&sub,true,code_size));
            }
            "strike" => {
                // The authority emits *only* the escaped text here (:146-147) —
                // no `<strike>` tag — so a strikethrough is visually plain text.
                let v = nd.get("v").cloned().unwrap_or(Value::Null);
                if ctx.text_style.author.is_some()||has_author_markup(&v)||crate::rust_pdf_notes::contains_marker(&v){out.extend(inline_markup_ctx(&normalize_inline(&v),style,tmpdir,resolve,ctx));continue;}
                let body = match &v {
                    Value::String(s) => s.clone(),
                    Value::Array(_) => inline_text(&v),
                    other => json_text(other),
                };
                out.push(Run {
                    content: RunContent::Text(body),
                    face: ctx.face,
                    size: ctx.size,
                    color: ctx.color,
                    href: ctx.href.clone(),
                    text_style: ctx.text_style,
                });
            }
            "link" => {
                let href = json_text(nd.get("href").unwrap_or(&Value::Null));
                let mut sub = ctx.clone();
                sub.color = link_color;
                sub.href = Some(href);
                let inner = nd.get("text").cloned().unwrap_or(Value::Null);
                let inner = normalize_inline(&inner);
                out.extend(inline_markup_ctx(&inner, style, tmpdir, resolve, &sub));
            }
            "image" => {
                let src_key = json_text(nd.get("src").unwrap_or(&Value::Null));
                let src = resolve(&src_key);
                match src {
                    Some(p) => {
                        if let Some((iw, ih)) = image_size_path(&p) {
                            if ih > 0.0 {
                                // `base = float(style['typography']['size']) * 1.3`
                                let base =
                                    plain_float(dig(style, &["typography", "size"]), 11.0) * 1.3;
                                let scale = (base / ih).min(1.0);
                                out.push(author_atom_run(Run {
                                    content: RunContent::Image(InlineImage {
                                        src: p.replace('\\', "/"),
                                        width: iw * scale,
                                        height: ih * scale,
                                        math: None,
                                    }),
                                    face: ctx.face,
                                    size: ctx.size,
                                    color: ctx.color,
                                    href: ctx.href.clone(),
                                    text_style: ctx.text_style,
                                }));
                                continue;
                            }
                        }
                        // `except Exception:` -> `_esc(nd['alt'] or nd['src'])`
                        let alt = json_text(nd.get("alt").unwrap_or(&Value::Null));
                        let body = if alt.is_empty() { src_key } else { alt };
                        out.extend(author_text_runs(&body,ctx,false,code_size));
                    }
                    // `if src:` false -> the node contributes nothing at all.
                    None => {}
                }
            }
            "math" => {
                let fallback = bool_or(nd.get("fallback").unwrap_or(&Value::Null), false);
                let latex = json_text(nd.get("latex").unwrap_or(&Value::Null));
                if let Err(code)=crate::math_spacing::require_vector_for_spacing_at_size(nd,ctx.size){
                    out.push(Run{content:RunContent::Error(PdfError::new(PdfErrorKind::Invalid,code)),face:ctx.face,size:ctx.size,color:ctx.color,href:ctx.href.clone(),text_style:ctx.text_style});continue;
                }
                if let Some(f) = crate::math_layout::layout_source(
                    &latex,
                    nd.get("omml").and_then(Value::as_str),
                    false,
                    ctx.size,
                ) {
                    out.push(author_atom_run(Run {
                        content: RunContent::Image(InlineImage::formula(f)),
                        face: ctx.face,
                        size: ctx.size,
                        color: ctx.color,
                        href: ctx.href.clone(),
                        text_style: ctx.text_style,
                    }));
                } else if has_spacing_markup(nd) {
                    out.push(Run{content:RunContent::Error(PdfError::new(PdfErrorKind::Invalid,"math_unsupported_extension")),face:ctx.face,size:ctx.size,color:ctx.color,href:ctx.href.clone(),text_style:ctx.text_style});
                } else if fallback {
                    out.extend(author_text_runs(&json_text(nd.get("latex").unwrap_or(&Value::Null)),ctx,false,code_size));
                } else {
                    let png = nd.get("png").and_then(|v| match v {
                        Value::Array(a) => Some(
                            a.iter()
                                .filter_map(|b| b.as_u64())
                                .map(|b| b as u8)
                                .collect::<Vec<u8>>(),
                        ),
                        _ => None,
                    });
                    let w = plain_float(nd.get("w").unwrap_or(&Value::Null), 0.0);
                    let h = plain_float(nd.get("h").unwrap_or(&Value::Null), 0.0);
                    if let Some(tag) = img_tag(tmpdir, png.as_deref(), w, h) {
                        out.push(author_atom_run(Run {
                            content: RunContent::Image(tag),
                            face: ctx.face,
                            size: ctx.size,
                            color: ctx.color,
                            href: ctx.href.clone(),
                            text_style: ctx.text_style,
                        }));
                    }
                }
            }
            _ => {}
        }
    }
    out
}

/// `nd['v'] if isinstance(nd['v'], list) else _parser.parse_inline(nd['v'])` —
/// a bare string is the degenerate one-text-node case.  Re-parsing markdown
/// inline here would need the parser; the AST the port is fed always carries
/// lists, so a string degrades to a single `text` node.
fn normalize_inline(v: &Value) -> Value {
    match v {
        Value::Array(_) => v.clone(),
        Value::Null => Value::Array(Vec::new()),
        other => Value::Array(vec![
            serde_json::json!({ "t": "text", "v": json_text(other) }),
        ]),
    }
}

/// `_parser.inline_text(nodes)` — the recursive plain-text projection, which is
/// also what `Paragraph.getPlainText()` answers for the TOC/outline path.
pub fn inline_text(nodes: &Value) -> String {
    let mut s = String::new();
    match nodes {
        Value::Array(a) => {
            for nd in a {
                let t = nd.get("t").and_then(|v| v.as_str()).unwrap_or("");
                match t {
                    "text" | "code" | "math" => {
                        if t == "math"
                            && !bool_or(nd.get("fallback").unwrap_or(&Value::Null), false)
                        {
                            continue;
                        }
                        s.push_str(&json_text(
                            nd.get("v").or(nd.get("latex")).unwrap_or(&Value::Null),
                        ));
                    }
                    "bold" | "italic" | "styled" | "author-styled" | "display" => s.push_str(&inline_text(
                        &normalize_inline(nd.get("v").unwrap_or(&Value::Null)),
                    )),
                    "br" => s.push('\n'),
                    "strike" => {
                        let v = nd.get("v").cloned().unwrap_or(Value::Null);
                        match &v {
                            Value::String(x) => s.push_str(x),
                            _ => s.push_str(&inline_text(&v)),
                        }
                    }
                    "link" => s.push_str(&inline_text(&normalize_inline(
                        nd.get("text").unwrap_or(&Value::Null),
                    ))),
                    "image" => s.push_str(&json_text(nd.get("alt").unwrap_or(&Value::Null))),
                    "note-marker"=>if let Ok(marker)=crate::rust_pdf_notes::Marker::parse(nd){s.push_str(&marker.text());},
                    _ => {}
                }
            }
        }
        Value::String(x) => s.push_str(x),
        _ => {}
    }
    s
}

/// Same, for the run stream a paragraph already holds.
pub fn runs_plain_text(runs: &[Run]) -> String {
    let mut s = String::new();
    for r in runs {
        match &r.content {
            RunContent::Text(t)|RunContent::NoteMarker{text:t,..} => s.push_str(t),
            RunContent::Image(_) => {}
            RunContent::Error(_) => {}
            RunContent::Break { .. } => s.push('\n'),
        }
    }
    s
}

