    /// `CASES["overflow"]`
    fn doc_overflow() -> Vec<Value> {
        let mut v = Vec::new();
        for i in 1..=25i64 {
            v.push(heading(2, &format!("Section {i}")));
            v.push(para(txts(&format!(
                "Paragraph {i} body sentence that keeps going and going to consume vertical \
                 room on the page."
            ))));
        }
        v
    }

    fn no_image(_src: &str) -> Option<String> {
        None
    }

    fn render(blocks: &[Value], style: &Value) -> RenderedDoc {
        let mut warns = Vec::new();
        build(
            &Value::Array(blocks.to_vec()),
            style,
            concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/../../scratch/rust_parity/s8_harness/tmp"
            ),
            &no_image,
            &mut warns,
        )
        .expect("pdf_render::build failed")
    }

    fn page_texts(doc: &RenderedDoc) -> Vec<String> {
        doc.pages.iter().map(|p| p.text.clone()).collect()
    }

    #[test]
    fn pdf_callouts_render_localized_titles_and_typed_borders_without_markers() {
        let kinds = ["NOTE", "TIP", "IMPORTANT", "WARNING", "CAUTION"];
        let source = kinds
            .iter()
            .map(|kind| format!("> [!{kind}]\n> Evidence for {kind}: **check** $x^2$.\n\n"))
            .collect::<String>();
        let blocks = crate::md_ast::to_render_json(&crate::md_ast::parse(&source).blocks);
        let style = style_for(
            json!({"calloutTitles":{"note":"提示","tip":"建议","important":"重要","warning":"警告","caution":"注意"}}),
        );
        let geom = DocGeometry::from_style(&style);
        let st = Styles::build(&style, "MicrosoftYaHei");
        let mut warnings = Vec::new();
        let story = build_story(
            &blocks,
            &style,
            "",
            &no_image,
            &st,
            "MicrosoftYaHei",
            &geom,
            &mut warnings,
            &[],
        );
        let colors: Vec<_> = story
            .iter()
            .filter_map(|f| {
                if let Flowable::Table(t) = f {
                    t.line_before.map(|(_, c)| c)
                } else {
                    None
                }
            })
            .collect();
        assert_eq!(colors.len(), 5);
        for pair in colors.windows(2) {
            assert_ne!(pair[0], pair[1]);
        }
        let doc = build(&blocks, &style, "", &no_image, &mut warnings).unwrap();
        let text = page_texts(&doc).join("\n");
        for title in ["提示", "建议", "重要", "警告", "注意"] {
            assert!(text.contains(title), "missing {title}");
        }
        for kind in kinds {
            assert!(text.contains(&format!("Evidence for {kind}")));
        }
        assert!(!text.contains("[!"));
        let bytes = write_pdf(&doc);
        assert!(!lopdf::Document::load_mem(&bytes)
            .unwrap()
            .get_pages()
            .is_empty());
    }

    #[test]
    fn internal_links_and_toc_use_real_paginated_destinations() {
        let source = "# Start\n\n[First](#same) [Second](#same-1) [中文](#%E4%B8%AD%E6%96%87) [Missing](#absent) [Site](https://example.org)\n\n## Same\n\nBody\n\n<!-- pagebreak -->\n\n## Same\n\n## 中文\n\nEnd\n";
        let blocks = crate::md_ast::to_render_json(&crate::md_ast::parse(source).blocks);
        let style = style_for(json!({"toc":{"enabled":true}}));
        let mut warnings = Vec::new();
        let rendered = build(&blocks, &style, "", &no_image, &mut warnings).unwrap();
        assert!(warnings.iter().any(|s| s == "pdf_anchor_missing: absent"));
        let bytes = write_pdf(&rendered);
        let pdf = lopdf::Document::load_mem(&bytes).unwrap();
        let pages = pdf.get_pages();
        let names: std::collections::HashMap<_, _> = rendered
            .pages
            .iter()
            .enumerate()
            .flat_map(|(pi, page)| {
                let page_id = pages[&(pi as u32 + 1)];
                page.items.iter().filter_map(move |item| match item {
                    DrawItem::Destination { name, top } => Some((name.as_str(), (page_id, *top))),
                    _ => None,
                })
            })
            .collect();
        assert_ne!(names["same"].0, names["same-1"].0);
        let mut internal = 0;
        let mut external = 0;
        for (pi, page) in rendered.pages.iter().enumerate() {
            let dict = pdf.get_dictionary(pages[&(pi as u32 + 1)]).unwrap();
            let expected: Vec<_> = page
                .items
                .iter()
                .filter_map(|item| match item {
                    DrawItem::Link { href, .. } if href != "#absent" => Some(href.as_str()),
                    _ => None,
                })
                .collect();
            let Some(annotations) = dict.get(b"Annots").ok().and_then(|v| v.as_array().ok()) else {
                assert!(expected.is_empty());
                continue;
            };
            assert_eq!(annotations.len(), expected.len());
            for (reference, href) in annotations.iter().zip(expected) {
                let annot = pdf
                    .get_dictionary(reference.as_reference().unwrap())
                    .unwrap();
                if let Some(fragment) = href.strip_prefix('#') {
                    let target = percent_encoding::percent_decode_str(fragment).decode_utf8_lossy();
                    let dest = annot.get(b"Dest").unwrap().as_array().unwrap();
                    assert_eq!(dest[0].as_reference().unwrap(), names[target.as_ref()].0);
                    assert_eq!(dest[1].as_name().unwrap(), b"XYZ");
                    assert!(
                        (dest[3].as_float().unwrap() as f64 - names[target.as_ref()].1).abs()
                            < 0.01
                    );
                    assert!(annot.get(b"A").is_err());
                    internal += 1;
                } else {
                    let action = annot.get(b"A").unwrap().as_dict().unwrap();
                    assert_eq!(action.get(b"S").unwrap().as_name().unwrap(), b"URI");
                    external += 1;
                }
            }
        }
        assert!(internal >= 7, "body links plus four clickable TOC entries");
        assert_eq!(external, 1);
    }

