    #[test]
    fn default__accented_matches_oracle_text() {
        let d = render(&doc_accented(), &style_for(json!({})));
        assert_eq!(d.pages.len(), 1);
        let first="Über Größe: café, crème brûlée, señor, ¿cómo? — yes \u{201c}quoted\u{201d} and \u{2018}single\u{2019} \u{2026}";
        let last="ellipsis\u{2026}";
        // FontTools 4.63.0, original DejaVu 2.37, integer /W at 11pt:
        // the first line fits; adding the original space and next complete
        // word crosses the 481.2283pt frame. Preserve the exact original text.
        let first_original=433.345;
        let last_original=48.444;
        let combined_original=485.287;
        assert!((d.geom.avail-481.2283).abs()<0.0001);
        assert!(first_original<d.geom.avail&&combined_original>d.geom.avail);
        let advance=|wanted:&str| {
            let spans=d.pages[0].items.iter().find_map(|item|if let DrawItem::Text{text,spans,..}=item {
                (text==wanted).then_some(spans)
            }else{None}).expect("the exact authored accented line must be present");
            for span in spans {
                let Face::Embedded(face)=span.face else {panic!("accented body line lost the owned font")};
                let info=d.embedded.faces[face as usize];assert!(!info.fake_bold);
                assert!(d.embedded.fonts[info.slot].as_ref().unwrap().base_name.ends_with("+DejaVuSans"));
            }
            spans.iter().map(|span|span.advance).sum::<f64>()
        };
        assert!((advance(first)-first_original).abs()<1e-6);
        assert!((advance(last)-last_original).abs()<1e-6);
        assert_eq!(d.pages[0].text,format!("1\nCafé naïve\n{first}\n{last}\nParagraph two with ñ, ç, ø and Æß.\n"));
    }

