    #[test]
    fn default__overflow_is_four_pages_and_wraps_owned_regular_in_frame() {
        let d = render(&doc_overflow(), &style_for(json!({})));
        // The retained first P15 run measured four actual pages. Regular body
        // now uses bundled DejaVu; no-pack bold headings retain their old role.
        assert_eq!(d.pages.len(), 4, "owned Regular pagination");
        let frame = 481.2283;
        assert!((d.geom.avail-frame).abs()<0.0001);
        let left = d.geom.left+FRAME_PAD;
        // Independent FontTools 4.63.0, original DejaVu 2.37 (sha256 7da195a7...),
        // quantized /W for every source scalar. Not measured from this output.
        let original_width = |scalar:char| -> i64 { match scalar {
            ' '|'.'=>318, '0'..='9'=>636, 'P'=>603, 'a'=>613, 'b'|'d'|'g'|'p'=>635,
            'c'=>550, 'e'=>615, 'h'|'n'|'u'=>634, 'i'|'l'=>278, 'k'=>579,
            'm'=>974, 'o'=>612, 'r'=>411, 's'=>521, 't'=>392, 'v'|'y'=>592,
            _=>panic!("unexpected overflow source scalar {scalar:?}"),
        }};
        let first = "Paragraph 1 body sentence that keeps going and going to consume vertical room on the page.";
        assert!((first.chars().map(original_width).sum::<i64>() as f64*11./1000.-524.425).abs()<1e-9);
        let mut headings=Vec::new();
        let mut paragraphs=vec![Vec::<String>::new();25];
        let mut active=None;
        for page in &d.pages {
            for item in &page.items {
                let DrawItem::Text{x,spans,text,..}=item else {continue};
                if text==&page.number.to_string() {continue;}
                if let Some(section)=text.strip_prefix("Section ") {
                    let section:usize=section.parse().unwrap();
                    assert!((1..=25).contains(&section));headings.push(section);active=Some(section);
                    continue;
                }
                let section=active.expect("a body line must follow its section heading");
                paragraphs[section-1].push(text.clone());
                let mut position=*x;
                assert!((position-left).abs()<1e-6,"body line left edge {position}");
                let mut copied=String::new();
                for span in spans {
                    assert_eq!(span.size,11.);
                    let Face::Embedded(face)=span.face else {panic!("ordinary body line lost its owned program")};
                    let info=d.embedded.faces[face as usize];assert!(!info.fake_bold);
                    let program=d.embedded.fonts[info.slot].as_ref().unwrap();
                    assert!(program.base_name.ends_with("+DejaVuSans"));
                    assert_eq!(span.bytes.len()%2,0);
                    let start=position;
                    for bytes in span.bytes.chunks_exact(2) {
                        let cid=u16::from_be_bytes([bytes[0],bytes[1]]) as usize;
                        let unicode=&program.unicode[cid];
                        let scalar=unicode.chars().next().unwrap();assert_eq!(unicode.chars().count(),1);
                        let width=original_width(scalar);assert_eq!(program.widths[cid],width);
                        copied.push(scalar);position+=width as f64*span.size/1000.;
                        assert!(position<=left+frame+0.0001,"actual glyph passed the usable frame: {position}");
                    }
                    assert!((position-start-span.advance).abs()<1e-6);
                }
                assert_eq!(&copied,text);
            }
        }
        assert_eq!(headings,(1..=25).collect::<Vec<_>>(),"each Section must appear exactly once and in order");
        for (index,lines) in paragraphs.iter().enumerate() {
            let expected=format!("Paragraph {} body sentence that keeps going and going to consume vertical room on the page.",index+1);
            assert_eq!(lines.len(),2,"paragraph {} must wrap the owned width",index+1);
            assert_eq!(lines.join(" ").split_whitespace().collect::<Vec<_>>(),expected.split_whitespace().collect::<Vec<_>>(),
                "paragraph {} changed, duplicated or reordered content",index+1);
        }
        assert_eq!(crate::pdf_fonts::proportional_advance('P',false,11.),None,"render clears its owned context");
    }

    #[test]
    fn default__overflow_no_context_helvetica_helper_keeps_afm_width() {
        // A direct helper call without an export context still uses Helvetica
        // AFM. Its one-line result is separate from the two-line owned output.
        assert_eq!(crate::pdf_fonts::proportional_advance('P',false,11.),None);
        let line = "Paragraph 1 body sentence that keeps going and going to consume vertical room on the page.";
        let w = str_width(line, FaceStyle::Regular, Face::Helvetica, 11.0);
        let st = Styles::build(&style_for(json!({})), "MicrosoftYaHei");
        let runs = inline_markup(&Value::Array(txts(line)),&style_for(json!({})),"T:/tmp",&no_image);
        let lines = paragraph_lines(&runs, &st.body, 481.2283);
        assert!(w <= 481.2283, "measured {w} against the 481.2283 pt frame");
        assert_eq!(lines.len(),1,"no-context Helvetica-width line");
        assert!(str_width("Paragraph 1 body sentence that keeps going and going to consume vertical room on the",
            FaceStyle::Regular,Face::Helvetica,11.0)<w);
    }

