    // ------------------------------------------ numeric formatting

    #[test]
    fn py_repr_float_follows_cppython_shortest_repr() {
        assert_eq!(py_repr_float(1.0), "1.0");
        assert_eq!(py_repr_float(11.0), "11.0");
        assert_eq!(py_repr_float(0.5), "0.5");
        assert_eq!(py_repr_float(-0.25), "-0.25");
        assert_eq!(py_repr_float(1.0 / 3.0), "0.3333333333333333");
        assert_eq!(py_repr_float(2.0 / 3.0), "0.6666666666666666");
        assert_eq!(py_repr_float(1e20), "1e+20");
        assert_eq!(fp_str(595.275591), "595.275591");
        // the writer keeps the shortest form, so 612 is a legal MediaBox number
        // (reportlab emits "612.0"); the value is what a reader sees
        assert_eq!(fp_str(612.0), "612");
        // reportlab's utils.fp_str is "%.6f" with trailing zeroes stripped'
        assert_eq!(fp_str(841.8897637795276), "841.889764");
        assert_eq!(fp_str(0.0), "0");
    }

    #[test]
    fn mm_unit_and_page_size_table() {
        assert_eq!(MM, 72.0 / 2.54 / 10.0);
        // `page_map()` already multiplies the mm table by `mm` -> points
        assert_eq!(page_map("A4"), Some((210.0 * MM, 297.0 * MM)));
        assert_eq!(page_map("A5"), Some((148.0 * MM, 210.0 * MM)));
        assert_eq!(page_map("B5"), Some((176.0 * MM, 250.0 * MM)));
        assert_eq!(page_map("Legal"), Some((215.9 * MM, 355.6 * MM)));
        // Letter is the size whose mm table lands on whole points
        assert_eq!(py_round(page_map("Letter").unwrap().0, 6), 612.0);
        assert_eq!(py_round(page_map("Letter").unwrap().1, 6), 792.0);
        assert_eq!(page_map("nope"), None);
        // `page_dimensions()` is the styles.py helper that answers in mm
        assert_eq!(page_dimensions(&default_style()), (210.0, 297.0));
        assert_eq!(
            page_dimensions(&style_for(json!({"page": {"size": "Letter",
                                                         "orientation": "landscape"}}))),
            (279.4, 215.9),
            "page_dimensions() swaps for landscape"
        );
        assert_eq!(ta_get("center"), Some(TA_CENTER));
        assert_eq!(ta_get("justify"), Some(TA_JUSTIFY));
        assert_eq!(ta_get("weird"), None);
    }

